'use strict';

// MODULES //

var floor = require( '@stdlib/math/base/special/floor' );
var fmod = require( '@stdlib/math/base/special/fmod' );
var reinterpret = require( '@stdlib/strided/base/reinterpret-complex' );


// MAIN //

/**
* Converts a real-valued array in FFTPACK half-complex format to a complex-valued array.
*
* @param {NonNegativeInteger} N - length of the original real sequence
* @param {Collection} hc - input array in FFTPACK half-complex format
* @param {integer} strideHc - stride length for `hc`
* @param {NonNegativeInteger} offsetHc - starting index for `hc`
* @param {(Complex128Array|Complex64Array)} out - output complex array
* @param {integer} strideOut - stride length for `out`
* @param {NonNegativeInteger} offsetOut - starting index for `out`
* @returns {(Complex128Array|Complex64Array)} output complex array
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
* var Complex128Array = require( '@stdlib/array/complex128' );
* var floor = require( '@stdlib/math/base/special/floor' );
* var rffti = require( '@stdlib/fft/base/fftpack/generic/rffti' );
* var rfftf = require( '@stdlib/fft/base/fftpack/generic/rfftf' );
*
* var N = 4;
* var w = new Float64Array( ( 2*N ) + 34 );
* rffti( N, w, 1, 0 );
*
* var r = new Float64Array( [ 1.0, 2.0, 3.0, 4.0 ] );
* rfftf( N, r, 1, 0, w, 1, 0 );
* // r => <Float64Array>[ 10.0, -2.0, 2.0, -2.0 ]
*
* var out = new Complex128Array( floor( N/2 ) + 1 );
* hc2c( N, r, 1, 0, out, 1, 0 );
* // out => <Complex128Array>[ 10.0, 0.0, -2.0, 2.0, -2.0, 0.0 ]
*/
function hc2c( N, hc, strideHc, offsetHc, out, strideOut, offsetOut ) {
	var view;
	var so;
	var io;
	var M;
	var k;

	if ( N <= 0 ) {
		return out;
	}
	// Reinterpret the complex output array as a real-valued array of interleaved real and imaginary components:
	view = reinterpret( out, 0 );

	// Adjust the stride and offset for the real-valued view:
	so = strideOut * 2;
	io = offsetOut * 2;

	// Resolve the number of interior complex coefficients:
	M = floor( ( N - 1 ) / 2 );

	// DC component:
	view[ io ] = hc[ offsetHc ];
	view[ io + 1 ] = 0.0; // Always purely real
	offsetHc += strideHc;
	io += so;

	// Complex coefficients for frequencies k = 1, ..., M:
	for ( k = 0; k < M; k++ ) {
		view[ io ] = hc[ offsetHc ];                // real part
		view[ io + 1 ] = hc[ offsetHc + strideHc ]; // imaginary part
		offsetHc += 2 * strideHc;
		io += so;
	}

	// Nyquist component (only when N is even):
	if ( fmod( N, 2 ) === 0 ) {
		view[ io ] = hc[ offsetHc ];
		view[ io + 1 ] = 0.0; // Always purely real
	}
	return out;
}


// EXPORTS //

module.exports = hc2c;
